  const [workspace,setWorkspace]=useState<any>({folders:[],projects:[],shared:[]}),[folder,setFolder]=useState<string|null>(null),[sharedView,setSharedView]=useState(false),[search,setSearch]=useState('');
  const [authMode,setAuthMode]=useState('signup'),[email,setEmail]=useState(''),[password,setPassword]=useState('');
  const [name,setName]=useState(''),[saveFolder,setSaveFolder]=useState(''),[shareTarget,setShareTarget]=useState<any>(null),[links,setLinks]=useState<any[]>([]),[access,setAccess]=useState<any>({members:[],invites:[]}),[link,setLink]=useState(''),[inviteEmail,setInviteEmail]=useState('');
  const [drawing,setDrawing]=useState<any>(null),[drawingJob,setDrawingJob]=useState(''),[reviewed,setReviewed]=useState(false),[title,setTitle]=useState(''),[material,setMaterial]=useState('Steel'),[density,setDensity]=useState(7850),[hidden,setHidden]=useState(false),[notes,setNotes]=useState(''),[page,setPage]=useState(0);
  const [engineering,setEngineering]=useState<any[]>([]),[service,setService]=useState('costing'),[kind,setKind]=useState('weld'),[construction,setConstruction]=useState('laser_rib'),[brief,setBrief]=useState('');
  const [qty,setQty]=useState(10),[matCost,setMatCost]=useState(''),[hours,setHours]=useState(''),[cycle,setCycle]=useState(''),[rate,setRate]=useState(''),[margin,setMargin]=useState(''),[rateBasis,setRateBasis]=useState(''),[costResult,setCostResult]=useState<any>(null),[previousCost,setPreviousCost]=useState('');
