  async function attempt(fn:()=>Promise<void>) {setError('');try{await fn();}catch(e){setError(e instanceof Error?e.message:String(e));}finally{setBusy('');setJobId('');}}
  async function refreshMe(){const me=await api('/me');setUser(me.user);setCaps(me.capabilities);return me;}
